/*
	Deploy: cột IsValid / IsMainUnit / IsTeachUnit + store ADD/EDIT/GET/GETALL
	Table : HRS_Task (điều động công tác)
	Date  : 2025-09-22
	Cách chạy:
		SSMS → chọn đúng database → F5 chạy toàn file.
		Không chạy lại file Link Deploy cũ sau file này.
*/

-- ===== Cột bảng =====
If Not Exists (
	Select 1
	From sys.columns
	Where object_id = Object_Id(N'dbo.HRS_Task')
		and name = N'IsValid'
)
Begin
	Alter Table [dbo].[HRS_Task]
	Add [IsValid] bit Not Null Constraint [DF_HRS_Task_IsValid] Default (1)
End
Go

If Not Exists (
	Select 1
	From sys.columns
	Where object_id = Object_Id(N'dbo.HRS_Task')
		and name = N'IsMainUnit'
)
Begin
	Alter Table [dbo].[HRS_Task]
	Add [IsMainUnit] bit Not Null Constraint [DF_HRS_Task_IsMainUnit] Default (0)
End
Go

If Not Exists (
	Select 1
	From sys.columns
	Where object_id = Object_Id(N'dbo.HRS_Task')
		and name = N'IsTeachUnit'
)
Begin
	Alter Table [dbo].[HRS_Task]
	Add [IsTeachUnit] bit Not Null Constraint [DF_HRS_Task_IsTeachUnit] Default (0)
End
Go

-- ===== HRS_Task_ADD =====
If Object_Id(N'dbo.HRS_Task_ADD', N'P') Is Null
	Exec(N'Create Procedure [dbo].[HRS_Task_ADD] As Begin Set Nocount On; End');
Go

Alter Procedure [dbo].[HRS_Task_ADD]
(
	@EmployeeID bigint = null,
	@TaskFrom date,
	@TaskTo date = null,
	@RequestUser bigint = null,
	@OtherDepartmentID int = 0,
	@OtherPositionID nvarchar(20) = 0,
	@PositionID nvarchar(20) = 0,
	@Work nvarchar(200) = null,
	@DecidedNo nvarchar(20) = null,
	@DecidedDate date = null,
	@DecidedUser bigint = 0,
	@IsSigned bit = 0,
	@Description nvarchar(200) = null,
	@CreatedUser nvarchar(20),
	@FromDepartmentID int = 0,
	@ToDepartmentID int = 0,
	@DecidedDepartmentName nvarchar(50) = null,
	@DecidedFullName nvarchar(50) = null,
	@ToOfficeName nvarchar(50) = null,
	@ToDepartmentName nvarchar(50) = null,
	@CurrentPositionID nvarchar(20) = 0,
	@EndTask_DecidedNo nvarchar(20) = null,
	@EndTask_DecidedDate date = null,
	@EndTask_DecidedUser bigint = 0,
	@EndTask_IsSigned bit = 0,
	@EndTask_Description nvarchar(200) = null,
	@EndTask_DecidedDepartmentName nvarchar(50) = null,
	@EndTask_DecidedFullName nvarchar(50) = null,
	@TaskTypeID int = 0,
	@Link nvarchar(500) = null,
	@IsValid bit = 1,
	@IsMainUnit bit = 0,
	@IsTeachUnit bit = 0
)
As
Begin
	Set Nocount Off

	Insert Into [HRS_Task]
	(
		[EmployeeID],
		[TaskFrom],
		[TaskTo],
		[RequestUser],
		[OtherDepartmentID],
		[OtherPositionID],
		[PositionID],
		[Work],
		[DecidedNo],
		[DecidedDate],
		[DecidedUser],
		[IsSigned],
		[Description],
		[CreatedUser],
		[FromDepartmentID],
		[ToDepartmentID],
		[DecidedDepartmentName],
		[DecidedFullName],
		[ToOfficeName],
		[ToDepartmentName],
		[CurrentPositionID],
		[EndTask_DecidedNo],
		[EndTask_DecidedDate],
		[EndTask_DecidedUser],
		[EndTask_IsSigned],
		[EndTask_Description],
		[EndTask_DecidedDepartmentName],
		[EndTask_DecidedFullName],
		[TaskTypeID],
		[Link],
		[IsValid],
		[IsMainUnit],
		[IsTeachUnit]
	)
	Values
	(
		@EmployeeID,
		@TaskFrom,
		@TaskTo,
		@RequestUser,
		@OtherDepartmentID,
		@OtherPositionID,
		@PositionID,
		@Work,
		@DecidedNo,
		@DecidedDate,
		@DecidedUser,
		@IsSigned,
		@Description,
		@CreatedUser,
		@FromDepartmentID,
		@ToDepartmentID,
		@DecidedDepartmentName,
		@DecidedFullName,
		@ToOfficeName,
		@ToDepartmentName,
		@CurrentPositionID,
		@EndTask_DecidedNo,
		@EndTask_DecidedDate,
		@EndTask_DecidedUser,
		@EndTask_IsSigned,
		@EndTask_Description,
		@EndTask_DecidedDepartmentName,
		@EndTask_DecidedFullName,
		@TaskTypeID,
		@Link,
		@IsValid,
		@IsMainUnit,
		@IsTeachUnit
	)

	Select Cast(Scope_Identity() As bigint)
End
Go

