		[Work] = @Work,
		[DecidedNo] = @DecidedNo,
		[DecidedDate] = @DecidedDate,
		[DecidedUser] = @DecidedUser,
		[IsSigned] = @IsSigned,
		[Description] = @Description,
		[UpdatedDate] = Getdate(),
		[UpdatedUser] = @UpdatedUser,
		[FromDepartmentID] = @FromDepartmentID,
		[ToDepartmentID] = @ToDepartmentID,
		[DecidedDepartmentName] = @DecidedDepartmentName,
		[DecidedFullName] = @DecidedFullName,
		[ToOfficeName] = @ToOfficeName,
		[ToDepartmentName] = @ToDepartmentName,
		[CurrentPositionID] = @CurrentPositionID,
		[EndTask_DecidedNo] = @EndTask_DecidedNo,
		[EndTask_DecidedDate] = @EndTask_DecidedDate,
		[EndTask_DecidedUser] = @EndTask_DecidedUser,
		[EndTask_IsSigned] = @EndTask_IsSigned,
		[EndTask_Description] = @EndTask_Description,
		[EndTask_DecidedDepartmentName] = @EndTask_DecidedDepartmentName,
		[EndTask_DecidedFullName] = @EndTask_DecidedFullName,
		[TaskTypeID] = @TaskTypeID,
		[Link] = @Link,
		[IsValid] = @IsValid,
		[IsMainUnit] = @IsMainUnit,
		[IsTeachUnit] = @IsTeachUnit
	Where [TaskID] = @TaskID
End
Go

-- ===== HRS_Task_GET =====
