#region Import Excel

private void ImportExcel()
{
    if (!UserSession.HasPermission(PERMISSION_ADD))
    {
        MessageManager.Warning("Bạn không có quyền nhập dữ liệu!");
        return;
    }

    if (MessageManager.Confirm("Nhập Excel sẽ XÓA toàn bộ quá trình công tác hiện tại rồi thêm mới theo EmployeeCode.\r\nDữ liệu cũ được backup bảng HRS_Task_Bak_20250922.\r\nBạn chắc chắn muốn tiếp tục?") != System.Windows.Forms.DialogResult.Yes)
        return;

    OpenFileDialog dlg = new OpenFileDialog();
    dlg.Filter = "Excel (*.xlsx;*.xls)|*.xlsx;*.xls";
    dlg.Title = "Chọn file QUÁ TRÌNH CÔNG TÁC HRS_TASK";
    if (dlg.ShowDialog() != DialogResult.OK)
        return;

    DataTable dtbExcel = ReadExcelToTable(dlg.FileName);
    if (dtbExcel == null || dtbExcel.Rows.Count == 0)
    {
        MessageManager.Warning("Không đọc được dữ liệu Excel. Cài Microsoft Access Database Engine nếu file .xlsx, hoặc lưu thành .xls.");
        return;
    }

    if (FindExcelColumn(dtbExcel, "EmployeeCode", "Mã NV", "Ma NV", "Mã nhân viên", "Ma nhan vien", "Mã") < 0)
    {
        MessageManager.Warning("Excel phải có cột EmployeeCode (hoặc Mã NV).");
        return;
    }

    HRS_Employee objEmployee = new HRS_Employee();
    DataTable dtbEmployee = objEmployee.GetAll();
    if (dtbEmployee == null)
    {
        ErrorManager.Error("Không tải được danh sách nhân viên!");
        return;
    }

    DataTable dtbPosition = null;
    try
    {
        dtbPosition = new GEN_Position().Search();
    }
    catch
    {
        dtbPosition = null;
    }

    DataTable dtbTaskType = HRS_TaskTypeService.Table;

    System.Text.StringBuilder sbError = new System.Text.StringBuilder();
    int intError = 0;
    int intOk = 0;

    HRS_Task obj = new HRS_Task();
    obj.BeginTransaction();
    if (!obj.DeleteAllHard())
    {
        obj.RollBackTransaction();
        ErrorManager.Error("Không xóa được dữ liệu cũ. Hãy chạy patch store HRS_Task_DELETE_ALL trước.\r\n" + (obj.ErrorException != null ? obj.ErrorException.Message : ""));
        return;
    }

    for (int i = 0; i < dtbExcel.Rows.Count; i++)
    {
        DataRow drw = dtbExcel.Rows[i];
        string strCode = GetExcelValue(drw, dtbExcel, "EmployeeCode", "Mã NV", "Ma NV", "Mã nhân viên", "Ma nhan vien", "Mã");
        if (strCode == "")
            continue;

        long? lngEmployeeID = FindEmployeeID(dtbEmployee, strCode);
        if (lngEmployeeID == null)
        {
            intError++;
            sbError.AppendLine(String.Format("Dòng {0}: không tìm thấy EmployeeCode [{1}]", i + 2, strCode));
            continue;
        }

        DateTime? dtmFrom = ParseExcelDate(GetExcelValue(drw, dtbExcel, "TaskFrom", "Từ ngày", "Tu ngay", "Ngày bắt đầu", "Ngay bat dau", "Ngày đảm nhận"));
        DateTime? dtmDecided = ParseExcelDate(GetExcelValue(drw, dtbExcel, "DecidedDate", "Ngày QĐ", "Ngày quyết định", "Ngay QD"));
        if (dtmFrom == null)
            dtmFrom = dtmDecided;
        if (dtmFrom == null)
        {
            intError++;
            sbError.AppendLine(String.Format("Dòng {0}: mã {1} thiếu Từ ngày / TaskFrom", i + 2, strCode));
            continue;
        }

        HRS_Task item = new HRS_Task();
        item.IDB = obj.IDB;
        item.EmployeeID = lngEmployeeID;
        item.TaskFrom = dtmFrom;
        item.TaskTo = ParseExcelDate(GetExcelValue(drw, dtbExcel, "TaskTo", "Đến ngày", "Den ngay", "Ngày kết thúc"));
        item.DecidedNo = Truncate(GetExcelValue(drw, dtbExcel, "DecidedNo", "Số QĐ", "So QD", "Số quyết định"), 20);
        item.DecidedDate = dtmDecided;
        item.PositionID = FindPositionID(dtbPosition, GetExcelValue(drw, dtbExcel, "PositionID", "PositionName", "Chức vụ", "Chuc vu"));
        item.CurrentPositionID = FindPositionID(dtbPosition, GetExcelValue(drw, dtbExcel, "CurrentPositionID", "CurrentPositionName", "Chức vụ đang giữ", "Chuc vu dang giu"));
        if (item.CurrentPositionID == "0")
            item.CurrentPositionID = item.PositionID;
        item.OtherPositionID = "0";
        item.OtherDepartmentID = 0;
        item.FromDepartmentID = 0;
        item.ToDepartmentID = 0;
        item.DecidedUser = 0;
        item.EndTask_DecidedUser = 0;
        item.Work = Truncate(GetExcelValue(drw, dtbExcel, "Work", "Công việc", "Cong viec"), 200);
        item.Description = Truncate(GetExcelValue(drw, dtbExcel, "Description", "Ghi chú", "Ghi chu"), 200);
        item.DecidedDepartmentName = Truncate(GetExcelValue(drw, dtbExcel, "DecidedDepartmentName", "Nơi quyết định", "Noi quyet dinh"), 50);
        item.DecidedFullName = Truncate(GetExcelValue(drw, dtbExcel, "DecidedFullName", "Người quyết định", "Nguoi quyet dinh"), 50);
        item.ToOfficeName = Truncate(GetExcelValue(drw, dtbExcel, "ToOfficeName", "Nơi đi", "Noi di"), 50);
        item.ToDepartmentName = Truncate(GetExcelValue(drw, dtbExcel, "ToDepartmentName", "Nơi đến", "Noi den"), 50);
        item.EndTask_DecidedNo = Truncate(GetExcelValue(drw, dtbExcel, "EndTask_DecidedNo", "Số QĐ miễn nhiệm"), 20);
        item.EndTask_DecidedDate = ParseExcelDate(GetExcelValue(drw, dtbExcel, "EndTask_DecidedDate", "Ngày QĐ miễn nhiệm"));
        item.TaskTypeID = FindTaskTypeID(dtbTaskType, GetExcelValue(drw, dtbExcel, "TaskTypeID", "TaskTypeName", "TaskTypeCode", "Loại QĐ", "Loại quyết định", "Loai QD"));
        item.IsSigned = ParseExcelBit(GetExcelValue(drw, dtbExcel, "IsSigned", "Đã ký", "Da ky"), false);
        item.IsValid = ParseExcelBit(GetExcelValue(drw, dtbExcel, "IsValid", "Còn hiệu lực", "Con hieu luc", "Còn HL"), true);
        item.IsMainUnit = ParseExcelBit(GetExcelValue(drw, dtbExcel, "IsMainUnit", "Đơn vị chính", "Don vi chinh", "ĐV chính"), false);
        item.IsTeachUnit = ParseExcelBit(GetExcelValue(drw, dtbExcel, "IsTeachUnit", "Đơn vị giảng dạy", "Don vi giang day", "ĐV giảng dạy"), false);
        item.CreatedUser = UserSession.Username;

        if (!item.Add())
        {
            MessageManager.Warning(String.Format("Dòng {0}: mã {1} lỗi thêm — dữ liệu cũ được giữ nguyên.\r\n{2}\r\n{3}",
                i + 2,
                strCode,
                item.ErrorException != null ? item.ErrorException.Message : "",
                sbError.ToString()));
            return;
        }
        intOk++;
    }

    if (intOk == 0)
    {
        obj.RollBackTransaction();
        MessageManager.Warning("Không có dòng nào nhập được. Dữ liệu cũ được giữ nguyên.\r\n" + sbError.ToString());
        return;
    }

    obj.CommitTransaction();
    string strActionLog = String.Format("Nhập Excel quá trình công tác: {0} dòng, bỏ {1} dòng. File: {2}", intOk, intError, dlg.FileName);
    new SystemObject.SYS_ActionLog().WriteActionLog("Nhập Excel công tác", strActionLog, SystemObject.ActionLogType.ADD, 2, UserSession.Username);
    MessageManager.Warning(String.Format("Đã nhập {0} dòng. Bỏ / lỗi {1} dòng.\r\n{2}", intOk, intError, sbError.ToString()));
    new Thread(LoadData).Start();
}

private DataTable ReadExcelToTable(string strPath)
{
    string strExt = System.IO.Path.GetExtension(strPath).ToLower();
    string strConn;
    if (strExt == ".xls")
        strConn = "Provider=Microsoft.Jet.OLEDB.4.0;Data Source=" + strPath + ";Extended Properties=\"Excel 8.0;HDR=YES;IMEX=1\"";
    else
        strConn = "Provider=Microsoft.ACE.OLEDB.12.0;Data Source=" + strPath + ";Extended Properties=\"Excel 12.0 Xml;HDR=YES;IMEX=1\"";

    System.Data.OleDb.OleDbConnection conn = new System.Data.OleDb.OleDbConnection(strConn);
    try
    {
        conn.Open();
        DataTable dtbSchema = conn.GetOleDbSchemaTable(System.Data.OleDb.OleDbSchemaGuid.Tables, null);
        if (dtbSchema == null || dtbSchema.Rows.Count == 0)
            return null;
        string strSheet = dtbSchema.Rows[0]["TABLE_NAME"].ToString();
        System.Data.OleDb.OleDbDataAdapter adp = new System.Data.OleDb.OleDbDataAdapter("Select * From [" + strSheet + "]", conn);
        DataTable dtb = new DataTable();
        adp.Fill(dtb);
        return dtb;
    }
    catch (Exception objEx)
    {
        ErrorManager.Error("Đọc Excel bị lỗi: " + objEx.Message);
        return null;
    }
    finally
    {
        conn.Close();
    }
}

private int FindExcelColumn(DataTable dtb, params string[] aliases)
{
    for (int i = 0; i < dtb.Columns.Count; i++)
    {
        string strCol = NormalizeName(dtb.Columns[i].ColumnName);
        for (int j = 0; j < aliases.Length; j++)
        {
            if (strCol == NormalizeName(aliases[j]))
                return i;
        }
    }
    return -1;
}

private string GetExcelValue(DataRow drw, DataTable dtb, params string[] aliases)
{
    int intCol = FindExcelColumn(dtb, aliases);
    if (intCol < 0)
        return "";
    if (Convert.IsDBNull(drw[intCol]))
        return "";
    return Convert.ToString(drw[intCol]).Trim();
}

private string NormalizeName(string str)
{
    if (str == null)
        return "";
    string s = DCore.Filter.FilterVietkey(str).ToLower();
    s = s.Replace(" ", "").Replace("_", "").Replace("-", "").Replace(".", "");
    return s;
}

private DateTime? ParseExcelDate(string str)
{
    if (str == null || str == "")
        return null;
    double dbl;
    if (double.TryParse(str, System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out dbl))
    {
        if (dbl > 20000 && dbl < 80000)
            return DateTime.FromOADate(dbl);
    }
    DateTime dtm;
    if (DateTime.TryParse(str, System.Globalization.CultureInfo.GetCultureInfo("vi-VN"), System.Globalization.DateTimeStyles.None, out dtm))
        return dtm;
    if (DateTime.TryParse(str, out dtm))
        return dtm;
    return null;
}

private bool ParseExcelBit(string str, bool bolDefault)
{
    if (str == null || str == "")
        return bolDefault;
    string s = DCore.Filter.FilterVietkey(str).Trim().ToLower();
    if (s == "1" || s == "true" || s == "x" || s == "co" || s == "yes" || s == "y")
        return true;
    if (s == "0" || s == "false" || s == "khong" || s == "no" || s == "n")
        return false;
    return bolDefault;
}

private long? FindEmployeeID(DataTable dtbEmployee, string employeeCode)
{
    if (dtbEmployee == null || employeeCode == null)
        return null;
    string strCode = employeeCode.Trim();
    foreach (DataRow drw in dtbEmployee.Rows)
    {
        if (Convert.ToString(drw["EmployeeCode"]).Trim() != strCode)
            continue;
        if (dtbEmployee.Columns.Contains("IsDeleted") && !Convert.IsDBNull(drw["IsDeleted"]) && Convert.ToBoolean(drw["IsDeleted"]))
            continue;
        return Convert.ToInt64(drw["EmployeeID"]);
    }
    return null;
}

private string FindPositionID(DataTable dtbPosition, string text)
{
    if (dtbPosition == null || text == null || text.Trim() == "")
        return "0";
    string strText = text.Trim();
    string strTextEn = NormalizeName(strText);
    foreach (DataRow drw in dtbPosition.Rows)
    {
        if (dtbPosition.Columns.Contains("PositionID") && Convert.ToString(drw["PositionID"]).Trim() == strText)
            return Convert.ToString(drw["PositionID"]);
        if (dtbPosition.Columns.Contains("PositionCode") && Convert.ToString(drw["PositionCode"]).Trim() == strText)
            return Convert.ToString(drw["PositionID"]);
        if (dtbPosition.Columns.Contains("PositionName") && NormalizeName(Convert.ToString(drw["PositionName"])) == strTextEn)
            return Convert.ToString(drw["PositionID"]);
    }
    return "0";
}

private int FindTaskTypeID(DataTable dtbType, string text)
{
    if (dtbType == null || text == null || text.Trim() == "")
        return 1;
    string strText = text.Trim();
    string strTextEn = NormalizeName(strText);
    foreach (DataRow drw in dtbType.Rows)
    {
        if (Convert.IsDBNull(drw["TaskTypeID"]))
            continue;
        if (Convert.ToString(drw["TaskTypeID"]).Trim() == strText)
            return Convert.ToInt32(drw["TaskTypeID"]);
        if (dtbType.Columns.Contains("TaskTypeCode") && Convert.ToString(drw["TaskTypeCode"]).Trim() == strText)
            return Convert.ToInt32(drw["TaskTypeID"]);
        if (dtbType.Columns.Contains("TaskTypeName") && NormalizeName(Convert.ToString(drw["TaskTypeName"])) == strTextEn)
            return Convert.ToInt32(drw["TaskTypeID"]);
    }
    return 1;
}

private string Truncate(string str, int intMax)
{
    if (str == null)
        return "";
    if (str.Length <= intMax)
        return str;
    return str.Substring(0, intMax);
}

